module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);

    wire w1, w2;

    assign w1 = a & b;
    assign w2 = c & d;
    assign out = w1 | w2;
    assign out_n = ~out;

endmodule

module tb_TopModule;
    reg a, b, c, d;
    wire out, out_n;

    TopModule uut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .out(out),
        .out_n(out_n)
    );

    integer i;
    reg expected_out;

    initial begin
        for (i = 0; i < 16; i = i + 1) {a, b, c, d} = i[3:0];
        #10;
        for (i = 0; i < 16; i = i + 1) {
            {a, b, c, d} = i[3:0];
            #10;
            expected_out = (i[3] & i[2]) | (i[1] & i[0]);
            if (out !== expected_out || out_n !== ~expected_out) begin
                $display("SELFFAIL: a=%b b=%b c=%b d=%b -> out=%b out_n=%b (expected out=%b)", 
                         a, b, c, d, out, out_n, expected_out);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

